export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-sub-0001", "section": "service", "who": "reader", "text": "В ПЯТОК СВЕТЛЫЯ СЕДМИЦЫ ВЕЧЕРА По 9-м часе, во светильничном, облачится настоятель во всю священную одежду. И став пред святою трапезою с кадильницею, знаменует крестовидно, и возглашает глаголя:"},
  {"id": "cu-sub-0002", "section": "service", "who": "reader", "text": "Благослове́н Бог наш всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sub-0003", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-sub-0004", "section": "service", "who": "reader", "text": "Ами́нь."},
  {"id": "cu-sub-0005", "section": "service", "who": "rubric", "text": "И той начинает:"},
  {"id": "cu-sub-0006", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0007", "section": "service", "who": "rubric", "text": "Трижды. И мы тойжде отвещаем трижды."},
  {"id": "cu-sub-0008", "section": "service", "who": "reader", "text": "И глаголет настоятель преждереченныя стихи: Первый стих:"},
  {"id": "cu-sub-0009", "section": "service", "who": "reader", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-sub-0010", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь:"},
  {"id": "cu-sub-0011", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых:"},
  {"id": "cu-sub-0012", "section": "service", "who": "rubric", "text": "Весь по единожды."},
  {"id": "cu-sub-0013", "section": "service", "who": "rubric", "text": "Вторый стих:"},
  {"id": "cu-sub-0014", "section": "service", "who": "reader", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-sub-0015", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-sub-0016", "section": "service", "who": "reader", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-sub-0017", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0018", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-sub-0019", "section": "service", "who": "reader", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-sub-0020", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0021", "section": "service", "who": "reader", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-sub-0022", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0023", "section": "service", "who": "reader", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-sub-0024", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0025", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-sub-0026", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-sub-0027", "section": "service", "who": "reader", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0028", "section": "service", "who": "rubric", "text": "Таже ектениа великая от диакона:"},
  {"id": "cu-sub-0029", "section": "service", "who": "deacon", "text": "Ми́ром Го́споду помо́лимся."},
  {"id": "cu-sub-0030", "section": "service", "who": "rubric", "text": "Подобает ведати, яко по внегда начати иерею, кадит святую трапезу по обычаю и весь олтарь, вечер, на"},
  {"id": "cu-sub-0031", "section": "service", "who": "deacon", "text": "Го́споди воззва́х:"},
  {"id": "cu-sub-0032", "section": "service", "who": "rubric", "text": "на Утрени, в начале канона исходит и кадит храм и лики и братию по обыкновенному чину."},
  {"id": "cu-sub-0033", "section": "service", "who": "choir", "text": "На Го́споди воззва́х: поставим стихов 6. И поем стихиры воскресны, глас 8. Стих:"},
  {"id": "cu-sub-0034", "section": "service", "who": "choir", "text": "А́ще беззако́ния на́зриши, Го́споди, Го́споди, кто постои́т? Я́ко у Тебе́ очище́ние есть."},
  {"id": "cu-sub-0035", "section": "service", "who": "choir", "text": "Вече́рнюю песнь, / и слове́сную слу́жбу, / Тебе́, Христе́, прино́сим, / я́ко благоволи́л еси́ поми́ловати нас Воскресе́нием. Стих:"},
  {"id": "cu-sub-0036", "section": "service", "who": "choir", "text": "И́мене ра́ди Твоего́ потерпе́х Тя, Го́споди, потерпе́ душа́ моя́ в сло́во Твое́, упова́ душа́ моя́ на Го́спода."},
  {"id": "cu-sub-0037", "section": "service", "who": "choir", "text": "Го́споди, Го́споди, / не отве́ржи нас от Твоего́ лица́, / но благоволи́ поми́ловати нас Воскресе́нием. Стих:"},
  {"id": "cu-sub-0038", "section": "service", "who": "choir", "text": "От стра́жи у́тренния до но́щи, от стра́жи у́тренния да упова́ет Изра́иль на Го́спода."},
  {"id": "cu-sub-0039", "section": "service", "who": "choir", "text": "Ра́дуйся, Сио́не Святы́й, / ма́ти церкве́й, Бо́жие жили́ще, / Ты бо прия́л еси́ пе́рвый, / оставле́ние грехо́в, Воскресе́нием."},
  {"id": "cu-sub-0040", "section": "service", "who": "choir", "text": "Восточны три, глас тойже. Стих:"},
  {"id": "cu-sub-0041", "section": "service", "who": "choir", "text": "Я́ко у Го́спода ми́лость, и мно́гое у Него́ избавле́ние, и Той изба́вит Изра́иля от всех беззако́ний eго́."},
  {"id": "cu-sub-0042", "section": "service", "who": "choir", "text": "Е́же от Бо́га Отца́ Сло́во, / пре́жде век Ро́ждшееся, / в после́дняя же времена́, / То́ежде от Неискусобра́чныя вопло́щшееся во́лею, / распя́тие сме́ртное претерпе́: / и дре́вле умерщвле́ннаго челове́ка спасе́ / Свои́м Воскресе́нием. Стих:"},
  {"id": "cu-sub-0043", "section": "service", "who": "choir", "text": "Хвали́те Го́спода вси язы́цы, похвали́те Его́ вси лю́дие."},
  {"id": "cu-sub-0044", "section": "service", "who": "choir", "text": "Е́же из ме́ртвых Твое́ Воскресе́ние славосло́вим Христе́, / и́мже свободи́л еси́ Ада́мский род от а́дова мучи́тельства: / и дарова́л еси́ мiрови я́ко Бог жизнь ве́чную / и ве́лию ми́лость. Стих:"},
  {"id": "cu-sub-0045", "section": "service", "who": "choir", "text": "Я́ко утверди́ся ми́лость Его́ на нас, и и́стина Госпо́дня пребыва́ет во век."},
  {"id": "cu-sub-0046", "section": "service", "who": "choir", "text": "Сла́ва Тебе́, Христе́ Спа́се, / Сы́не Бо́жий Единоро́дный, / пригвозди́выйся на Кресте́, / и воскресы́й из гро́ба тридне́вен."},
  {"id": "cu-sub-0047", "section": "service", "who": "choir", "text": "Слава: Тебе́ сла́вим, Го́споди, / во́лею нас ра́ди Крест претерпе́вшаго, / и Тебе́ покланя́емcя, Всеси́льне Спа́се, / не отве́ржи нас от Лица́ Твоего́, / но услы́ши и спаси́ ны / Воскресе́нием Твои́м, Человеколю́бче."},
  {"id": "cu-sub-0048", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Царь Небе́сный / за человеколю́бие на земли́ яви́ся, / и с челове́ки поживе́: / от Де́вы бо Чи́стыя плоть прие́мый, / и из Нея́ проше́дый с восприя́тием. / Еди́н есть Сын, сугу́б естество́м, / но не Ипоста́сию. / Те́мже соверше́нна Того́ Бо́га / и соверше́нна Челове́ка вои́стину пропове́дающе, / испове́дуем Христа́ Бо́га на́шего: / Его́же моли́, Ма́ти Безневе́стная, / поми́ловатися душа́м на́шим."},
  {"id": "cu-sub-0049", "section": "service", "who": "choir", "text": "Вход с кадильницею. Све́те ти́хий:"},
  {"id": "cu-sub-0050", "section": "service", "who": "rubric", "text": "Прокимен, глас 8:"},
  {"id": "cu-sub-0051", "section": "service", "who": "choir", "text": "Дал еси́ достоя́ние / боя́щимся Тебе́, Го́споди. Стих:"},
  {"id": "cu-sub-0052", "section": "service", "who": "choir", "text": "От коне́ц земли́ к Тебе́ воззва́х. Стих:"},
  {"id": "cu-sub-0053", "section": "service", "who": "choir", "text": "Покры́юся в кро́ве крил Твои́х. Стих:"},
  {"id": "cu-sub-0054", "section": "service", "who": "choir", "text": "Та́ко воспою́ и́мени Твоему́ во ве́ки. И паки:"},
  {"id": "cu-sub-0055", "section": "service", "who": "choir", "text": "Дал еси́ достоя́ние боя́щимся Тебе́, Го́споди."},
  {"id": "cu-sub-0056", "section": "service", "who": "rubric", "text": "Посем ектениа:"},
  {"id": "cu-sub-0057", "section": "service", "who": "choir", "text": "Рцем вси: и Сподо́би, Го́споди, в ве́чер сей: Таже:"},
  {"id": "cu-sub-0058", "section": "service", "who": "choir", "text": "Испо́лним вече́рнюю моли́тву:"},
  {"id": "cu-sub-0059", "section": "service", "who": "choir", "text": "На стиховне стихира воскресна, глас 8:"},
  {"id": "cu-sub-0060", "section": "service", "who": "choir", "text": "Возше́л еси́ на Крест, Иису́се, / снизше́дый с Небесе́, / прише́л еси́ на смерть, Животе́ Безсме́ртный, / к су́щим во тьме Свет и́стинный, / к па́дшым всех Воскресе́ние, / просвеще́ние и Спа́се наш, сла́ва Тебе́."},
  {"id": "cu-sub-0061", "section": "service", "who": "choir", "text": "Таже стихиры Пасхи, глас 5. Стих:"},
  {"id": "cu-sub-0062", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-sub-0063", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-sub-0064", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-sub-0065", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-sub-0066", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-sub-0067", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-sub-0068", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-sub-0069", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-sub-0070", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0071", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-sub-0072", "section": "service", "who": "rubric", "text": "трижды, кроме конца стихиры."},
  {"id": "cu-sub-0073", "section": "service", "who": "rubric", "text": "Таже диакон:"},
  {"id": "cu-sub-0074", "section": "service", "who": "deacon", "text": "Прему́дрость. Мы же:"},
  {"id": "cu-sub-0075", "section": "service", "who": "deacon", "text": "Благослови́. Настоятель:"},
  {"id": "cu-sub-0076", "section": "service", "who": "deacon", "text": "Сый благослове́н Христо́с Бог наш: И мы:"},
  {"id": "cu-sub-0077", "section": "service", "who": "deacon", "text": "Утверди́, Бо́же:"},
  {"id": "cu-sub-0078", "section": "service", "who": "rubric", "text": "Таже настоятель, вместо: Слава Тебе Христе Боже:"},
  {"id": "cu-sub-0079", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы:"},
  {"id": "cu-sub-0080", "section": "service", "who": "deacon", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0081", "section": "service", "who": "rubric", "text": "И абие глаголет отпуст со Крестом:"},
  {"id": "cu-sub-0082", "section": "service", "who": "deacon", "text": "Христо́с воскресы́й из ме́ртвых:"},
  {"id": "cu-sub-0083", "section": "service", "who": "rubric", "text": "И прочее, якоже изъявися в конец Утрени."},
  {"id": "cu-sub-0084", "section": "service", "who": "rubric", "text": "И целуем святыя иконы. И входим в трапезу, и глаголем:"},
  {"id": "cu-sub-0085", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0086", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-sub-0087", "section": "service", "who": "deacon", "text": "Христе́ Бо́же благослови́:"},
  {"id": "cu-sub-0088", "section": "service", "who": "rubric", "text": "По востании же от трапезы, глаголем:"},
  {"id": "cu-sub-0089", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0090", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-sub-0091", "section": "service", "who": "deacon", "text": "С на́ми Бог Своею благодатию:"},
  {"id": "cu-sub-0092", "section": "service", "who": "deacon", "text": "В СУББОТУ СВЕТЛЫЯ СЕДМИЦЫ НА УТРЕНИ"},
  {"id": "cu-sub-0093", "section": "service", "who": "deacon", "text": "Прежде начала, вжигает кандила и свещи параекклисиарх. Таже клеплет в великий кампан, и в прочия. И собравшимся нам во храм, иерей полагает обычный поклон настоятелю, и отходит во святый олтарь, и взем кадильницу стоит пред святою Трапезою, кроме убо священническия одежды, епитрахилий точию возложь сверх мантии, кадит крестообразно, глаголя:"},
  {"id": "cu-sub-0094", "section": "service", "who": "deacon", "text": "Сла́ва Святе́й, и Единосу́щней, и Животворя́щей, и Нераздели́мей Тро́ице, всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sub-0095", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-sub-0096", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-sub-0097", "section": "service", "who": "choir", "text": "Начинает настоятель, с прочими служители, велегласно настоящий тропарь, во глас 5:"},
  {"id": "cu-sub-0098", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0099", "section": "service", "who": "choir", "text": "И мы тойжде поем подобне, со сладкопением. Поется же сей тропарь трижды от настоятеля, и трижды от нас."},
  {"id": "cu-sub-0100", "section": "service", "who": "choir", "text": "Таже настоятель глаголет стихи: Первый стих:"},
  {"id": "cu-sub-0101", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-sub-0102", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь весь по единожды:"},
  {"id": "cu-sub-0103", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: Вторый стих:"},
  {"id": "cu-sub-0104", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-sub-0105", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды. Третий стих:"},
  {"id": "cu-sub-0106", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-sub-0107", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sub-0108", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-sub-0109", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-sub-0110", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sub-0111", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-sub-0112", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sub-0113", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-sub-0114", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sub-0115", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-sub-0116", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-sub-0117", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0118", "section": "service", "who": "choir", "text": "В мирских же храмех облачится иерей в ризы. Таже ектениа великая."},
  {"id": "cu-sub-0119", "section": "service", "who": "rubric", "text": "И по возгласе абие поем канон, ирмос:"},
  {"id": "cu-sub-0120", "section": "service", "who": "choir", "text": "Воскресе́ния день:"},
  {"id": "cu-sub-0121", "section": "service", "who": "rubric", "text": "по дважды, тропари же на 10, с припевы:"},
  {"id": "cu-sub-0122", "section": "service", "who": "choir", "text": "Христо́с воскре́се: В Сла́ва, и ны́не:"},
  {"id": "cu-sub-0123", "section": "service", "who": "rubric", "text": "глаголем Богородичны господина Феофана, и господина Иосифа. Катавасия оба лика вкупе:"},
  {"id": "cu-sub-0124", "section": "service", "who": "choir", "text": "Воскресе́ния день: И последи:"},
  {"id": "cu-sub-0125", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0126", "section": "service", "who": "choir", "text": "Канон, глас 1. Песнь 1. Ирмос:"},
  {"id": "cu-sub-0127", "section": "service", "who": "choir", "text": "Воскресе́ния день, / просвети́мся, лю́дие. / Па́сха, Госпо́дня Па́сха, / от сме́рти бо к жи́зни, / и от земли́ к небеси́, / Христо́с Бог нас преведе́, / побе́дную пою́щия. Припев:"},
  {"id": "cu-sub-0128", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0129", "section": "service", "who": "choir", "text": "Очи́стим чу́вствия, и у́зрим / непристу́пным све́том / Воскресе́ния, Христа́ блиста́ющася, / и ра́дуйтеся, реку́ща, / я́сно да услы́шим, / побе́дную пою́ще. Припев:"},
  {"id": "cu-sub-0130", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0131", "section": "service", "who": "choir", "text": "Небеса́ у́бо досто́йно да веселя́тся, / земля́ же да ра́дуется, / да пра́зднует же мир, / ви́димый же весь и неви́димый: / Христо́с бо воста́, / весе́лие ве́чное."},
  {"id": "cu-sub-0132", "section": "service", "who": "choir", "text": "Иный канон Богородичен, подобен. Егоже краестрочие на первых тропарех: Феофа́нус. Глас тойже."},
  {"id": "cu-sub-0133", "section": "service", "who": "choir", "text": "Слава: Умерщвле́ния преде́л сломи́ла еси́, / ве́чную жизнь ро́ждшая Христа́, из гро́ба возсия́вшаго днесь, / Де́во Всенепоро́чная, и мир просвети́вшаго."},
  {"id": "cu-sub-0134", "section": "service", "who": "choir", "text": "И ныне: Воскре́сшаго ви́девши Сы́на Твоего́ и Бо́га, / ра́дуйся со апо́столы Богоблагода́тная Чи́стая, / и е́же ра́дуйся пе́рвее, я́ко всех ра́дости вина́, / восприя́ла еси́, Богома́ти Всенепоро́чная."},
  {"id": "cu-sub-0135", "section": "service", "who": "rubric", "text": "Катавасия оба лика вкупе:"},
  {"id": "cu-sub-0136", "section": "service", "who": "choir", "text": "Воскресе́ния день: И последи:"},
  {"id": "cu-sub-0137", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0138", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-sub-0139", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое, / не от ка́мене непло́дна чудоде́емое, / но нетле́ния исто́чник / из гро́ба одожди́вша Христа́, / в Не́мже утвержда́емся. Припев:"},
  {"id": "cu-sub-0140", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0141", "section": "service", "who": "choir", "text": "Ны́не вся испо́лнишася све́та, / не́бо же и земля́, и преиспо́дняя: / да пра́зднует у́бо вся тварь / воста́ние Христо́во, / в не́мже утвержда́ется. Припев:"},
  {"id": "cu-sub-0142", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0143", "section": "service", "who": "choir", "text": "Вчера́ спогребо́хся Тебе́ Христе́, / совостаю́ днесь / воскре́сшу Тебе́, / сраспина́хся Тебе́ вчера́, / Сам мя спросла́ви Спа́се во Ца́рствии Твое́м."},
  {"id": "cu-sub-0144", "section": "service", "who": "choir", "text": "Слава: На нетле́нную жизнь / прихожду́ днесь бла́гостию ро́ждшагося из Тебе́, Чи́стая, / и всем конце́м свет облиста́вшаго."},
  {"id": "cu-sub-0145", "section": "service", "who": "choir", "text": "И ныне: Бо́га, Его́же родила́ еси́ пло́тию, из ме́ртвых, / я́коже рече́, воста́вша ви́девши, Чи́стая, лику́й, / и Сего́ я́ко Бо́га Пречи́стая возвелича́й. Катавасия:"},
  {"id": "cu-sub-0146", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое: И тропарь:"},
  {"id": "cu-sub-0147", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0148", "section": "service", "who": "choir", "text": "Таже ектениа."},
  {"id": "cu-sub-0149", "section": "service", "who": "choir", "text": "Ипакои, глас 4:"},
  {"id": "cu-sub-0150", "section": "service", "who": "choir", "text": "Предвари́вшия у́тро я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго, / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-sub-0151", "section": "service", "who": "choir", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-sub-0152", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи / богоглаго́ливый Авваку́м / да ста́нет с на́ми и пока́жет / светоно́сна А́нгела / я́сно глаго́люща: / днесь спасе́ние ми́ру, / я́ко воскре́се Христо́с, / я́ко всеси́лен. Припев:"},
  {"id": "cu-sub-0153", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0154", "section": "service", "who": "choir", "text": "Му́жеский у́бо пол, / я́ко разве́рзый де́вственную утро́бу, / яви́ся Христо́с, / я́ко челове́к же, / А́гнец нарече́ся, / непоро́чен же, / я́ко невку́сен скве́рны, / на́ша Па́сха, / и я́ко Бог и́стинен / соверше́н рече́ся. Припев:"},
  {"id": "cu-sub-0155", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0156", "section": "service", "who": "choir", "text": "Я́ко единоле́тный а́гнец, / благослове́нный нам вене́ц Христо́с, / во́лею за всех закла́н бысть, / Па́сха чисти́тельная, / и па́ки из гро́ба кра́сное / пра́вды нам возсия́ Со́лнце. Припев:"},
  {"id": "cu-sub-0157", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0158", "section": "service", "who": "choir", "text": "Богооте́ц у́бо Дави́д / пред се́нным ковче́гом скака́ше игра́я, / лю́дие же Бо́жии святи́и, / образо́в сбытие́ зря́ще, / весели́мся Боже́ственне, / я́ко воскре́се Христо́с, / я́ко Всеси́лен."},
  {"id": "cu-sub-0159", "section": "service", "who": "choir", "text": "Слава: Созда́вый Ада́ма, Твоего́ пра́отца, Чи́стая, / зи́ждется от Тебе́, и сме́ртное жили́ще разори́ Свое́ю сме́ртию днесь, / и озари́ вся / боже́ственными блиста́ньми Воскресе́ния."},
  {"id": "cu-sub-0160", "section": "service", "who": "choir", "text": "И ныне: Его́же родила́ еси́ Христа́, / прекра́сно из ме́ртвых возсия́вша, Чи́стая зря́щи, / до́брая и непоро́чная в жена́х и кра́сная, / днесь во спасе́ние всех, со апо́столы ра́дующися, / Того́ прославля́й. Катавасия:"},
  {"id": "cu-sub-0161", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи: И тропарь:"},
  {"id": "cu-sub-0162", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0163", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-sub-0164", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́, / и вме́сто ми́ра песнь принесе́м Влады́це, / и Христа́ у́зрим / пра́вды Со́лнце, / всем жизнь возсия́юща. Припев:"},
  {"id": "cu-sub-0165", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0166", "section": "service", "who": "choir", "text": "Безме́рное Твое́ благоутро́бие, / а́довыми у́зами содержи́мии зря́ще, / к све́ту идя́ху Христе́, / весе́лыми нога́ми, / Па́сху хва́ляще ве́чную. Припев:"},
  {"id": "cu-sub-0167", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0168", "section": "service", "who": "choir", "text": "Присту́пим свещено́снии, / исходя́щу Христу́ из гро́ба, я́ко жениху́, / и спра́зднуем любопра́зднственными чи́нми / Па́сху Бо́жию спаси́тельную."},
  {"id": "cu-sub-0169", "section": "service", "who": "choir", "text": "Слава: Просвеща́ется боже́ственными луча́ми и живоно́сными / воскресе́ния Сы́на Твоего́, Богома́ти Пречи́стая, / и ра́дости исполня́ется / благочести́вых собра́ние."},
  {"id": "cu-sub-0170", "section": "service", "who": "choir", "text": "И ныне: Не разве́рзл еси́ врата́ де́вства в воплоще́нии, / гро́ба не разруши́л еси́ печа́тей, Царю́ созда́ния, / отону́дуже воскре́сшаго Тя зря́щи / Ма́ти, ра́довашеся. Катавасия:"},
  {"id": "cu-sub-0171", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́: И тропарь:"},
  {"id": "cu-sub-0172", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0173", "section": "service", "who": "choir", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-sub-0174", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́, / и сокруши́л еси́ вереи́ ве́чныя, / содержа́щия свя́занныя, Христе́, / и тридне́вен, я́ко от ки́та Ио́на, / воскре́сл еси́ от гро́ба. Припев:"},
  {"id": "cu-sub-0175", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0176", "section": "service", "who": "choir", "text": "Сохрани́в це́ла зна́мения Христе́, / воскре́сл еси́ от гро́ба, / ключи́ Де́вы не вреди́вый в рождестве́ Твое́м, / и отве́рзл еси́ нам ра́йския две́ри. Припев:"},
  {"id": "cu-sub-0177", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0178", "section": "service", "who": "choir", "text": "Спа́се мой, / живо́е же и неже́ртвенное заколе́ние, / я́ко Бог Сам Себе́ / во́лею приве́л Отцу́, / совоскреси́л еси́ всеро́днаго Ада́ма, / воскре́с от гро́ба."},
  {"id": "cu-sub-0179", "section": "service", "who": "choir", "text": "Слава: Возведе́ся дре́вле держи́мое сме́ртию и тле́нием, / воплоти́вшимся от Твоего́ пречи́стаго чре́ва, / к нетле́нней и присносу́щней жи́зни, / Богоро́дице Де́во."},
  {"id": "cu-sub-0180", "section": "service", "who": "choir", "text": "И ныне: Сни́де в преиспо́дняя земли́, / в ложесна́ Твоя́, Чи́стая, сше́дый, / и всели́выйся и воплоти́выйся па́че ума́, / и воздви́же с Собо́ю Ада́ма, / воскре́с от гро́ба. Катавасия:"},
  {"id": "cu-sub-0181", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́: И тропарь:"},
  {"id": "cu-sub-0182", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0183", "section": "service", "who": "choir", "text": "Ектениа."},
  {"id": "cu-sub-0184", "section": "service", "who": "choir", "text": "Таже кондак, глас 8:"},
  {"id": "cu-sub-0185", "section": "service", "who": "choir", "text": "А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко победитель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся, / и Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние. Икос:"},
  {"id": "cu-sub-0186", "section": "service", "who": "choir", "text": "Е́же пре́жде со́лнца Со́лнце заше́дшее иногда́ во гроб, / предвари́ша ко у́тру, и́щущия я́ко дне мvроно́сицы де́вы, / и друга́ ко друзе́й вопия́ху: / о други́ни! Прииди́те, воня́ми пома́жем те́ло живоно́сное и погребе́ное, / плоть воскреси́вшаго па́дшаго Ада́ма, лежа́щую во гро́бе. / И́дем, потщи́мся я́коже волсви́, и поклони́мся, / и принесе́м мvра я́ко да́ры, не в пелена́х, но в плащани́це обви́тому, / и пла́чим, и возопии́м: о Влады́ко, воста́ни, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-sub-0187", "section": "service", "who": "choir", "text": "И чтение."},
  {"id": "cu-sub-0188", "section": "service", "who": "choir", "text": "Таже глаголем:"},
  {"id": "cu-sub-0189", "section": "service", "who": "choir", "text": "Воскресе́ние Христо́во ви́девше, / поклони́мся Свято́му Го́споду Иису́су, / еди́ному безгре́шному, / Кресту́ Твоему́ покланя́емся, Христе́, / и свято́е Воскресе́ние Твое́ пое́м и сла́вим: / Ты бо еси́ Бог наш, / ра́зве Тебе́ ино́го не зна́ем, / и́мя Твое́ имену́ем. / Прииди́те вси ве́рнии, / поклони́мся Свято́му Христо́ву Воскресе́нию: / се бо прии́де Кресто́м ра́дость всему́ ми́ру. / Всегда́ благословя́ще Го́спода, / пое́м Воскресе́ние Его́: / распя́тие бо претерпе́в, / сме́ртию смерть разруши́. [Трижды.]"},
  {"id": "cu-sub-0190", "section": "service", "who": "choir", "text": "Воскре́с Иису́с от гро́ба, / я́коже прорече́, / даде́ нам живо́т ве́чный / и ве́лию ми́лость. [Трижды.]"},
  {"id": "cu-sub-0191", "section": "service", "who": "choir", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-sub-0192", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый, / быв Челове́к, / стра́ждет я́ко сме́ртен, / и стра́стию сме́ртное, / в нетле́ния облачи́т благоле́пие, / Еди́н благослове́н / отце́в Бог, и препросла́влен. Припев:"},
  {"id": "cu-sub-0193", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0194", "section": "service", "who": "choir", "text": "Жены́ с ми́ры богому́дрыя в след Тебе́ теча́ху, / Его́же, я́ко ме́ртва, со слеза́ми иска́ху, / поклони́шася ра́дующияся Живо́му Бо́гу, / и Па́сху та́йную / Твои́м, Христе́, ученико́м благовести́ша. Припев:"},
  {"id": "cu-sub-0195", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0196", "section": "service", "who": "choir", "text": "Сме́рти пра́зднуем умерщвле́ние, / а́дово разруше́ние, / ино́го жития́ ве́чнаго нача́ло, / и игра́юще пое́м Вино́внаго, / Еди́наго благослове́ннаго / отце́в Бо́га, и препросла́вленнаго. Припев:"},
  {"id": "cu-sub-0197", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0198", "section": "service", "who": "choir", "text": "Я́ко вои́стинну свяще́нная, / и всепра́зднственная сия́ спаси́тельная нощь, / и светоза́рная, / светоно́снаго дне, / воста́ния су́щи провозве́стница, / в не́йже безле́тный Свет из гро́ба пло́тски всем возсия́."},
  {"id": "cu-sub-0199", "section": "service", "who": "choir", "text": "Слава: Умертви́в Сын Твой смерть, Всенепоро́чная, / днесь всем сме́ртным пребыва́ющий живо́т во ве́ки веко́в дарова́, / Еди́н благослове́нный, / отце́в Бог и Препросла́вленный."},
  {"id": "cu-sub-0200", "section": "service", "who": "choir", "text": "И ныне: Всем ца́рствуяй созда́нием, / быв челове́к, / всели́ся в Твою́, Богоблагода́тная, утро́бу, / и распя́тие претерпе́в и смерть, / воскре́се боголе́пно, / совозста́вив нас, я́ко всеси́лен. Катавасия:"},
  {"id": "cu-sub-0201", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый: И тропарь:"},
  {"id": "cu-sub-0202", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0203", "section": "service", "who": "choir", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-sub-0204", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день, / Еди́н суббо́т Царь и Госпо́дь, / пра́здников пра́здник / и торжество́ есть торже́ств, / во́ньже благослови́м Христа́ во ве́ки. Припев:"},
  {"id": "cu-sub-0205", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0206", "section": "service", "who": "choir", "text": "Прииди́те, но́ваго виногра́да рожде́ния, / Боже́ственнаго весе́лия, / в наро́читом дни Воскресе́ния, / Ца́рствия Христо́ва приобщи́мся, / пою́ще Его́ / я́ко Бо́га во ве́ки. Припев:"},
  {"id": "cu-sub-0207", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sub-0208", "section": "service", "who": "choir", "text": "Возведи́ о́крест о́чи твои́, Сио́не, и виждь: / се бо приидо́ша к тебе́, / я́ко богосве́тлая свети́ла, / от за́пада, и се́вера, и мо́ря, / и восто́ка ча́да твоя́, / в тебе́ благословя́щая Христа́ во ве́ки. Припев:"},
  {"id": "cu-sub-0209", "section": "service", "who": "choir", "text": "Пресвята́я Тро́ице, Бо́же наш, сла́ва Тебе́. Троичен:"},
  {"id": "cu-sub-0210", "section": "service", "who": "choir", "text": "О́тче Вседержи́телю, и Сло́ве, и Ду́ше, / треми́ соединя́емое во Ипоста́сех Естество́, / Пресу́щественне и Пребоже́ственне, / в Тя крести́хомся, / и Тя благослови́м во вся ве́ки."},
  {"id": "cu-sub-0211", "section": "service", "who": "choir", "text": "Благослови́м Отца́ и Сы́на и Свята́го Ду́ха, Го́спода."},
  {"id": "cu-sub-0212", "section": "service", "who": "choir", "text": "Прии́де Тобо́ю в мир Госпо́дь, / Де́во Богоро́дице, / и чре́во а́дово расто́рг, / сме́ртным нам воскресе́ние дарова́, / те́мже благослови́м Его́ во ве́ки."},
  {"id": "cu-sub-0213", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в, ами́нь."},
  {"id": "cu-sub-0214", "section": "service", "who": "choir", "text": "Всю низложи́в сме́рти держа́ву / Сын Твой, Де́во, Свои́м воскресе́нием, / я́ко Бог кре́пкий совознесе́ нас и обожи́, / те́мже воспева́ем Его́ во ве́ки. Катавасия:"},
  {"id": "cu-sub-0215", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день: И тропарь:"},
  {"id": "cu-sub-0216", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sub-0217", "section": "service", "who": "choir", "text": "Песнь 9."},
  {"id": "cu-sub-0218", "section": "service", "who": "deacon", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца."},
  {"id": "cu-sub-0219", "section": "service", "who": "rubric", "text": "И первый лик ирмос:"},
  {"id": "cu-sub-0220", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-sub-0221", "section": "service", "who": "rubric", "text": "Таже вторый лик поет вторый припев:"},
  {"id": "cu-sub-0222", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / во́лею страда́вша, и погребе́на, / и Воскре́сшаго тридне́вно от гро́ба. И ирмос:"},
  {"id": "cu-sub-0223", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся:"},
  {"id": "cu-sub-0224", "section": "service", "who": "rubric", "text": "Таже первый лик поет:"},
  {"id": "cu-sub-0225", "section": "service", "who": "choir", "text": "Христо́с но́вая Па́сха, / Же́ртва жива́я, / А́гнец Бо́жий, / взе́мляй грехи́ ми́ра."},
  {"id": "cu-sub-0226", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго, / о сладча́йшаго Твоего́ гла́са! / С на́ми бо нело́жно / обеща́лся еси́ бы́ти, / до сконча́ния ве́ка Христе́: / Его́же, ве́рнии, / утвержде́ние наде́жди иму́ще, ра́дуемся."},
  {"id": "cu-sub-0227", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-sub-0228", "section": "service", "who": "rubric", "text": "Таже первый лик поет припев:"},
  {"id": "cu-sub-0229", "section": "service", "who": "choir", "text": "А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый: / лю́дие, весели́теся. И тропарь:"},
  {"id": "cu-sub-0230", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-sub-0231", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-sub-0232", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-sub-0233", "section": "service", "who": "choir", "text": "Возбуди́л еси́ усну́в ме́ртвыя от ве́ка, / ца́рски рыка́вый я́ко от Иу́ды лев. И тропарь:"},
  {"id": "cu-sub-0234", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-sub-0235", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-sub-0236", "section": "service", "who": "choir", "text": "Магдали́на Мари́я притече́ ко гро́бу, / и Христа́ ви́девши, / я́ко вертогра́даря вопроша́ше."},
  {"id": "cu-sub-0237", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая, Христе́! / О му́дросте, и Сло́ве Бо́жий, и си́ло! / Подава́й нам и́стее Тебе́ причаща́тися, / в невече́рнем дни Ца́рствия Твоего́."},
  {"id": "cu-sub-0238", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-sub-0239", "section": "service", "who": "choir", "text": "А́нгел облиста́яй жена́м вопия́ше: / преста́ните от слез, я́ко Христо́с воскре́се. И тропарь:"},
  {"id": "cu-sub-0240", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sub-0241", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-sub-0242", "section": "service", "who": "choir", "text": "Христо́с воскре́се, смерть попра́вый, / и ме́ртвыя воздви́гнувый, / лю́дие весели́теся. И тропарь:"},
  {"id": "cu-sub-0243", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sub-0244", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-sub-0245", "section": "service", "who": "choir", "text": "Днесь вся́ка тварь весели́тся и ра́дуется, / я́ко Христо́с воскре́се, и ад плени́ся. И тропарь:"},
  {"id": "cu-sub-0246", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sub-0247", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-sub-0248", "section": "service", "who": "choir", "text": "Днесь Влады́ка плени́ а́да, / воздви́гнувый ю́зники, я́же от ве́ка имя́ше лю́те одержи́мыя. И тропарь:"},
  {"id": "cu-sub-0249", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sub-0250", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-sub-0251", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Триипоста́снаго и Неразде́льнаго Божества́ держа́ву."},
  {"id": "cu-sub-0252", "section": "service", "who": "choir", "text": "Согла́сно Де́во, Тебе́ блажи́м ве́рнии: / ра́дуйся, Две́ре Госпо́дня, / ра́дуйся, Гра́де одушевле́нный, / ра́дуйся, Ея́же ра́ди нам ны́не возсия́ свет, / из Тебе́ Рожде́ннаго из ме́ртвых Воскресе́ния."},
  {"id": "cu-sub-0253", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-sub-0254", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-sub-0255", "section": "service", "who": "choir", "text": "Весели́ся и ра́дуйся боже́ственная Две́ре Све́та, / заше́дый бо Иису́с во гроб возсия́, / просия́в со́лнца светле́е, / и ве́рныя вся озари́в, / Богора́дованная Влады́чице."},
  {"id": "cu-sub-0256", "section": "service", "who": "rubric", "text": "Таже оба лика, сошедшеся вкупе, поют припев:"},
  {"id": "cu-sub-0257", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца. И ирмос:"},
  {"id": "cu-sub-0258", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́. И тропарь:"},
  {"id": "cu-sub-0259", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-sub-0260", "section": "service", "who": "rubric", "text": "трижды. И ектениа."},
  {"id": "cu-sub-0261", "section": "service", "who": "choir", "text": "Ексапостиларий. Самогласен:"},
  {"id": "cu-sub-0262", "section": "service", "who": "choir", "text": "Пло́тию усну́в, / я́ко мертв, / Царю́ и Го́споди, / тридне́вен воскре́сл еси́, / Ада́ма воздви́г от тли, / и упраздни́в смерть, / Па́сха нетле́ния, / ми́ра спасе́ние. [Трижды.]"},
  {"id": "cu-sub-0263", "section": "service", "who": "choir", "text": "На хвалитех стихиры воскресны на 4, глас 8: Стих:"},
  {"id": "cu-sub-0264", "section": "service", "who": "choir", "text": "Хвали́те Его́ на си́лах Его́, / хвали́те Его́ по мно́жеству вели́чествия Его́."},
  {"id": "cu-sub-0265", "section": "service", "who": "choir", "text": "Го́споди, а́ще и суди́лищу предста́л еси́ от Пила́та суди́мый, / но не отступи́л еси́ от престо́ла со Отце́м седя́: / и воскре́с из ме́ртвых, / мiр свободи́л еси́ от рабо́ты чужда́го, / я́ко Щедр и Человеколю́бец. Стих:"},
  {"id": "cu-sub-0266", "section": "service", "who": "choir", "text": "Хвали́те Его́ во гла́се тру́бнем, / хвалите Его́ во псалти́ри и гу́слех."},
  {"id": "cu-sub-0267", "section": "service", "who": "choir", "text": "Го́споди, а́ще и я́ко ме́ртва / во гро́бе иуде́и положи́ша, / но я́ко Царя́ спя́ща во́ини Тя стрежа́ху, / и я́ко живота́ сокро́вище, печа́тию печа́таша, / но воскре́сл еси́, / и по́дал еси́ нетле́ние душа́м на́шым. Стих:"},
  {"id": "cu-sub-0268", "section": "service", "who": "choir", "text": "Хвали́те Его́ в тимпа́не и ли́це, / хвали́те Его́ во стру́нах и орга́не."},
  {"id": "cu-sub-0269", "section": "service", "who": "choir", "text": "Го́споди, ору́жие на диа́вола / Крест Твой дал еси́ нам: / трепе́щет бо и трясе́тся, не терпя́ взира́ти на си́лу Его́: / я́ко ме́ртвыя возставля́ет, и смерть упраздни́. / Сего́ ра́ди покланя́емся / погребе́нию Твоему́ и воста́нию. Стих:"},
  {"id": "cu-sub-0270", "section": "service", "who": "choir", "text": "Хвали́те Его́ в кимва́лех доброгла́сных, хвали́те Его́ в кимва́лех восклица́ния, / вся́кое дыха́ние да хва́лит Го́спода."},
  {"id": "cu-sub-0271", "section": "service", "who": "choir", "text": "А́нгел Твой, Го́споди, / Воскресе́ние пропове́давый, / стра́жи у́бо устраши́, / жена́м же возгласи́, глаго́ля: / что и́щете Жива́го с ме́ртвыми? / Воскре́се Бог сый, / и вселе́нней жизнь дарова́."},
  {"id": "cu-sub-0272", "section": "service", "who": "choir", "text": "И стихиры Пасхи с припевы их, глас 5. Стих:"},
  {"id": "cu-sub-0273", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-sub-0274", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-sub-0275", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-sub-0276", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-sub-0277", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-sub-0278", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-sub-0279", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-sub-0280", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-sub-0281", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0282", "section": "service", "who": "choir", "text": "Таже настоящий тропарь, во глас 5, трижды:"},
  {"id": "cu-sub-0283", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0284", "section": "service", "who": "choir", "text": "Ектении, и отпуст, и час 1-й. Часы Пасхи."},
  {"id": "cu-sub-0285", "section": "service", "who": "choir", "text": "НА ЛИТУРГИИ"},
  {"id": "cu-sub-0286", "section": "service", "who": "rubric", "text": "Наченшу диакону:"},
  {"id": "cu-sub-0287", "section": "service", "who": "deacon", "text": "Благослови́ влады́ко."},
  {"id": "cu-sub-0288", "section": "service", "who": "rubric", "text": "Настоятелю же возгласившу:"},
  {"id": "cu-sub-0289", "section": "service", "who": "deacon", "text": "Благослове́но Ца́рство Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в. И мы:"},
  {"id": "cu-sub-0290", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-sub-0291", "section": "service", "who": "deacon", "text": "Настоятель поет с прочими служители во святом олтаре:"},
  {"id": "cu-sub-0292", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в. Трижды."},
  {"id": "cu-sub-0293", "section": "service", "who": "deacon", "text": "И лики тойжде, трижды."},
  {"id": "cu-sub-0294", "section": "service", "who": "choir", "text": "Настоятель глаголет припевы: Первый стих:"},
  {"id": "cu-sub-0295", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-sub-0296", "section": "service", "who": "choir", "text": "И на кийждо стих мы поем тропарь весь по единожды: Тропарь:"},
  {"id": "cu-sub-0297", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Вторый стих:"},
  {"id": "cu-sub-0298", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-sub-0299", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-sub-0300", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-sub-0301", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0302", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-sub-0303", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-sub-0304", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0305", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-sub-0306", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0307", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-sub-0308", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sub-0309", "section": "service", "who": "rubric", "text": "Таже настоятель поет вышшим гласом:"},
  {"id": "cu-sub-0310", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. Мы же:"},
  {"id": "cu-sub-0311", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0312", "section": "service", "who": "choir", "text": "Посем глаголет диакон ектению великую. По ектении же и по возгласе:"},
  {"id": "cu-sub-0313", "section": "service", "who": "choir", "text": "Антифон первый, псалом 65, глас 2. Стих 1:"},
  {"id": "cu-sub-0314", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви / вся земля́. Припев:"},
  {"id": "cu-sub-0315", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-sub-0316", "section": "service", "who": "rubric", "text": "И другий лик тойжде стих:"},
  {"id": "cu-sub-0317", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви вся земля́, / по́йте же и́мени Его́, дади́те сла́ву хвале́ Его́. Припев:"},
  {"id": "cu-sub-0318", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 2:"},
  {"id": "cu-sub-0319", "section": "service", "who": "choir", "text": "Рцы́те Бо́гу: коль стра́шна дела́ Твоя́, / во мно́жестве си́лы Твоея́ со́лжут Тебе́ врази́ Твои́. Припев:"},
  {"id": "cu-sub-0320", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 3:"},
  {"id": "cu-sub-0321", "section": "service", "who": "choir", "text": "Вся земля́ да покло́нится Тебе́, / и пое́т Тебе́, да пое́т же и́мени Твоему́ Вы́шний. Припев:"},
  {"id": "cu-sub-0322", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-sub-0323", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-sub-0324", "section": "service", "who": "rubric", "text": "Купно оба лика вышшим гласом:"},
  {"id": "cu-sub-0325", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-sub-0326", "section": "service", "who": "choir", "text": "Таже, ектениа малая."},
  {"id": "cu-sub-0327", "section": "service", "who": "choir", "text": "Антифон вторый, псалом 66, глас тойже. Стих 1:"},
  {"id": "cu-sub-0328", "section": "service", "who": "choir", "text": "Бо́же уще́дри ны / и благослови́ ны. Припев:"},
  {"id": "cu-sub-0329", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-sub-0330", "section": "service", "who": "rubric", "text": "Другая страна, тойже стих:"},
  {"id": "cu-sub-0331", "section": "service", "who": "choir", "text": "Бо́же, уще́дри ны и благослови́ ны, / просвети лице Твое́ на ны и поми́луй ны. Припев:"},
  {"id": "cu-sub-0332", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 2:"},
  {"id": "cu-sub-0333", "section": "service", "who": "choir", "text": "Да позна́ем на земли́ путь Твой, / во всех язы́цех спасе́ние Твое́. Припев:"},
  {"id": "cu-sub-0334", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 3:"},
  {"id": "cu-sub-0335", "section": "service", "who": "choir", "text": "Да испове́дятся Тебе́ лю́дие, Бо́же, / да испове́дятся Тебе́ лю́дие вси. Припев:"},
  {"id": "cu-sub-0336", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-sub-0337", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-sub-0338", "section": "service", "who": "rubric", "text": "Вкупе два лика:"},
  {"id": "cu-sub-0339", "section": "service", "who": "choir", "text": "Единоро́дный Сы́не и Сло́ве Бо́жий, Безсме́ртен Сый / и изво́ливый спасе́ния на́шего ра́ди / воплоти́тися от Святы́я Богоро́дицы и Присноде́вы Мари́и, / непрело́жно вочелове́чивыйся, / распны́йся же, Христе́ Бо́же, сме́ртию смерть попра́вый, / Еди́н Сый Святы́я Тро́ицы, / спрославля́емый Отцу́ и Свято́му Ду́ху, спаси́ нас."},
  {"id": "cu-sub-0340", "section": "service", "who": "choir", "text": "Таже, ектениа."},
  {"id": "cu-sub-0341", "section": "service", "who": "choir", "text": "Антифон 3-й, псалом 67, глас 5. Стих 1:"},
  {"id": "cu-sub-0342", "section": "service", "who": "choir", "text": "Да воскре́снет Бог / и расточа́тся врази́ Его́."},
  {"id": "cu-sub-0343", "section": "service", "who": "choir", "text": "Тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0344", "section": "service", "who": "rubric", "text": "Другая страна, той же стих:"},
  {"id": "cu-sub-0345", "section": "service", "who": "choir", "text": "Да воскре́снет Бог и расточа́тся врази́ Его́, / и да бежа́т от лица́ Его́ ненави́дящии Его́. Тропарь:"},
  {"id": "cu-sub-0346", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 2:"},
  {"id": "cu-sub-0347", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-sub-0348", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 3:"},
  {"id": "cu-sub-0349", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от лица́ Бо́жия, / а пра́ведницы да возвеселя́тся, да возра́дуются пред Бо́гом. Тропарь:"},
  {"id": "cu-sub-0350", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-sub-0351", "section": "service", "who": "rubric", "text": "И бывает вход. И возглашает диакон, аще есть, аще же ни, иерей:"},
  {"id": "cu-sub-0352", "section": "service", "who": "deacon", "text": "Прему́дрость, про́сти."},
  {"id": "cu-sub-0353", "section": "service", "who": "deacon", "text": "Мы же входное: В це́рквах благослови́те Бо́га, / Го́спода от исто́чник Изра́илевых."},
  {"id": "cu-sub-0354", "section": "service", "who": "deacon", "text": "И поем тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0355", "section": "service", "who": "deacon", "text": "Ипакои, глас 4: Предвари́вшия у́тро, я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-sub-0356", "section": "service", "who": "deacon", "text": "Слава, и ныне: кондак, глас 8: А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко Победи́тель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся! / И Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-sub-0357", "section": "service", "who": "deacon", "text": "Вместо же Трисвятаго: Ели́цы во Христа́ крести́стеся, / во Христа́ облеко́стеся: / аллилу́иа."},
  {"id": "cu-sub-0358", "section": "service", "who": "deacon", "text": "Прокимен, глас 3: Госпо́дь просвеще́ние мое́ и Спаси́тель мой, / кого́ убою́ся? Стих:"},
  {"id": "cu-sub-0359", "section": "service", "who": "deacon", "text": "Госпо́дь защи́титель живота́ моего́, от кого́ устрашу́ся?"},
  {"id": "cu-sub-0360", "section": "service", "who": "deacon", "text": "Деяния святых Апостол, зачало 8."},
  {"id": "cu-sub-0361", "section": "service", "who": "deacon", "text": "Во дни о́ны, держа́щуся исцеле́вшему хромо́му Петра́ и Иоа́нна, притеко́ша к ним вси лю́дие в притво́р, нарица́емый Соломо́нов, ужа́сни. Ви́дев же Петр отвещава́ше к лю́дем: му́жие Изра́ильтяне, что чудите́ся о сем, или́ на ны что взира́ете, я́ко свое́ю ли си́лою или́ благоче́стием сотвори́хом его́ ходи́ти? Бог Авраа́мов и Исаа́ков и Иа́ковль, Бог оте́ц на́ших, просла́ви О́трока Своего́ Иису́са, Его́же вы преда́сте, и отверго́стеся Его́ пред лице́м Пила́товым, су́ждьшу О́ному пусти́ти. Вы же Свята́го и Пра́веднаго отверго́стеся, и испроси́сте му́жа уби́йцу да́ти вам, Нача́льника же жи́зни уби́сте, Его́же Бог воскреси́ от ме́ртвых, ему́же мы свиде́тели есмы́. И о ве́ре и́мене Его́, сего́, его́же ви́дите и зна́ете, утверди́ и́мя Его́, и ве́ра, я́же Его́ ра́ди, даде́ ему́ всю це́лость сию́ пред все́ми ва́ми."},
  {"id": "cu-sub-0362", "section": "service", "who": "deacon", "text": "Аллилуиа, глас 5: Стих:"},
  {"id": "cu-sub-0363", "section": "service", "who": "deacon", "text": "Госпо́дь воцари́ся, в ле́поту облече́ся. Стих:"},
  {"id": "cu-sub-0364", "section": "service", "who": "deacon", "text": "И́бо утверди́ вселе́нную, я́же не подви́жится."},
  {"id": "cu-sub-0365", "section": "service", "who": "deacon", "text": "Евангелие от Иоанна, зачало 11."},
  {"id": "cu-sub-0366", "section": "service", "who": "deacon", "text": "Во вре́мя о́но, прии́де Иису́с и ученицы́ Его́ в жидо́вскую зе́млю, и ту живя́ше с ни́ми и креща́ше. Бе же Иоа́нн крестя́ во Ено́не близ Сали́ма, я́ко во́ды мно́ги бя́ху ту, и прихожда́ху и креща́хуся. Не у бо бе всажде́н в темни́цу Иоа́нн. Бысть же стяза́ние от учени́к Иоа́нновых со иуде́и о очище́нии. И приидо́ша ко Иоа́нну и реко́ша ему́: равви́, И́же бе с тобо́ю об он пол Иорда́на, Ему́же ты свиде́тельствовал еси́, се Сей креща́ет, и вси гряду́т к Нему́. Отвеща́ Иоа́нн и рече́: не мо́жет челове́к приима́ти ничесо́же, а́ще не бу́дет дано́ ему́ с небесе́. Вы са́ми мне свиде́тельствуете, я́ко рех: несмь аз Христо́с, но я́ко по́слан есмь пред Ним. Име́яй неве́сту жени́х есть, а друг женихо́в, стоя́ и послу́шая его́, ра́достию ра́дуется за глас женихо́в, сия́ у́бо ра́дость моя́ испо́лнися. О́ному подоба́ет расти́, мне же ма́литися. Гряды́й свы́ше над все́ми есть, сый от земли́ от земли́ есть и от земли́ глаго́лет, Гряды́й с небесе́ над все́ми есть. И е́же ви́де и слы́ша, сие́ свиде́тельствует, и свиде́тельства Его́ никто́же прие́млет. Прие́мый Его́ свиде́тельство ве́рова, я́ко Бог и́стинен есть."},
  {"id": "cu-sub-0367", "section": "service", "who": "deacon", "text": "И бывает по чину Божественная Литургиа Златоустаго."},
  {"id": "cu-sub-0368", "section": "service", "who": "deacon", "text": "Вместо же Достойно: поем: А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый, / лю́дие, весели́теся."},
  {"id": "cu-sub-0369", "section": "service", "who": "rubric", "text": "Таже ирмос, глас 1:"},
  {"id": "cu-sub-0370", "section": "service", "who": "deacon", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-sub-0371", "section": "service", "who": "deacon", "text": "Причастный: Те́ло Христо́во приими́те, / исто́чника безсме́ртнаго вкуси́те. / Аллилу́иа. трижды."},
  {"id": "cu-sub-0372", "section": "service", "who": "rubric", "text": "Егда же настоятель глаголет:"},
  {"id": "cu-sub-0373", "section": "service", "who": "deacon", "text": "Со стра́хом Бо́жиим и ве́рою приступи́те."},
  {"id": "cu-sub-0374", "section": "service", "who": "rubric", "text": "Мы вместо, Благословен грядый во имя Господне: поем:"},
  {"id": "cu-sub-0375", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-sub-0376", "section": "service", "who": "rubric", "text": "единожды. Настоятель глаголет:"},
  {"id": "cu-sub-0377", "section": "service", "who": "deacon", "text": "Спаси́ Бо́же лю́ди Твоя́: И мы:"},
  {"id": "cu-sub-0378", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-sub-0379", "section": "service", "who": "rubric", "text": "единожды. Егда же изглаголет иерей:"},
  {"id": "cu-sub-0380", "section": "service", "who": "priest", "text": "Всегда́ ны́не и при́сно: И мы:"},
  {"id": "cu-sub-0381", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-sub-0382", "section": "service", "who": "rubric", "text": "единожды. Посем ектениа. Вместо же, Буди имя Господне: и вместо псалма, Благословлю Господа: поем:"},
  {"id": "cu-sub-0383", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-sub-0384", "section": "service", "who": "rubric", "text": "дванадесять, и множае: дондеже анафора от игумена раздастся. Таже настоятель,"},
  {"id": "cu-sub-0385", "section": "service", "who": "priest", "text": "Благослове́ние Госпо́дне на вас:"},
  {"id": "cu-sub-0386", "section": "service", "who": "choir", "text": "Ами́нь."},
  {"id": "cu-sub-0387", "section": "service", "who": "rubric", "text": "Посем настоятель вместо, Слава Тебе Христе Боже: поет:"},
  {"id": "cu-sub-0388", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в."},
  {"id": "cu-sub-0389", "section": "service", "who": "rubric", "text": "И лик:"},
  {"id": "cu-sub-0390", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sub-0391", "section": "service", "who": "rubric", "text": "Посем настоятель глаголет отпуст со Крестом по обычаю."},
  {"id": "cu-sub-0392", "section": "service", "who": "choir", "text": "По заамвонной молитве, диaкон глаголет: Го́споду помо́лимся."},
  {"id": "cu-sub-0393", "section": "service", "who": "choir", "text": "Го́споди поми́луй."},
  {"id": "cu-sub-0394", "section": "service", "who": "choir", "text": "Иерeй глаголет молитву сию над артосом:"},
  {"id": "cu-sub-0395", "section": "service", "who": "choir", "text": "Го́споди Иису́се Христе́, Бо́же нaш, Хле́бе а́нгельский, Хле́бе живота́ ве́чнаго, сошeдый с Небесе́, напитaвый нaс во всесве́тлыя сия́ дни пи́щею духо́вною Твои́х Боже́ственных благодея́ний, триднeвнаго рaди и спаси́тельнаго воскресе́ния, при́зри и ны́не, смирeнно мо́лим Тя, на мольбы́ и благодаре́ния на́ша. И я́коже благослови́л еси́ пять хле́бов в пусты́не, и ны́не благослови́ хлеб сeй, я́ко да вси вкушaющии от него́, телeснаго и душeвнаго благословeния и здрaвия сподо́бятся благодaтию и щедро́тами Твоего́ человеколю́бия. Ты бо еси́ освящeние нaше, и Тебе́ слaву возсылaем со безначaльным Твои́м Отцо́м, и всесвяты́м, и благи́м, и животворя́щим Твои́м Ду́хом, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sub-0396", "section": "service", "who": "choir", "text": "Ами́нь. Раздробив же артос обычно, раздает всем верующим вместо антидора."},
];

